const MCP_ENDPOINT='/api/mcp';
async function callMcp(method:string,params:any){
 const response=await fetch(MCP_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json, text/event-stream'},body:JSON.stringify({jsonrpc:'2.0',id:Date.now(),method,params})});
 const body=await response.text();
 const contentType=response.headers.get('content-type')??'';
 if(!response.ok)throw new Error(`MCP request failed (${response.status} ${response.statusText}) at ${MCP_ENDPOINT}${body?`: ${body.slice(0,180)}`:''}`);
 if(!contentType.includes('application/json'))throw new Error(`MCP returned ${contentType||'an unknown content type'} instead of JSON at ${MCP_ENDPOINT}${body?`: ${body.slice(0,180)}`:''}`);
 try{return JSON.parse(body)}catch{throw new Error(`MCP returned malformed JSON at ${MCP_ENDPOINT}: ${body.slice(0,180)||'empty response'}`)}
}

