 const [tab,setTab]=useState('playground'); const [tool,setTool]=useState('show_dashboard');const [args,setArgs]=useState('{}'); const [result,setResult]=useState<any>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [ms,setMs]=useState<number|null>(null);const [origin,setOrigin]=useState('');const [copied,setCopied]=useState(false);const [frame,setFrame]=useState(0);
 useEffect(()=>setOrigin(location.origin),[]);
 useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();for(const definition of toolDefinitions){try{Promise.resolve(context.registerTool({...definition,async execute(input:unknown){const data:any=await callMcp('tools/call',{name:definition.name,arguments:input});if(data.error||data.result?.isError)throw Error(data.error?.message??data.result?.content?.[0]?.text??'Invalid tool input');setTool(definition.name);setArgs(JSON.stringify(input,null,2));setResult(data.result);setTab('playground');return data.result;}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}return()=>lifecycle.abort()},[]);
 async function run(method='tools/call',params:any={name:tool,arguments:JSON.parse(args)}){setBusy(true);setError('');setResult(null);setMs(null);const start=performance.now();try{const data:any=await callMcp(method,params);if(data.error||data.result?.isError)throw Error(data.error?.message??data.result?.content?.[0]?.text??'The MCP tool rejected this request.');setResult(data.result);setMs(Math.round(performance.now()-start));}catch(e){setError(e instanceof Error?e.message:String(e));setMs(Math.round(performance.now()-start))}finally{setBusy(false)}}
