"use client";
import {useState} from 'react';
import {dashboardTemplates,TemplateId} from '@/lib/templates';
import {Button} from '@/components/ui/button';
import {Moon,Sun,ExternalLink,Copy,Check,PanelLeft,Search,Bell,ArrowUpRight,Truck,CalendarDays,WalletCards,ShoppingBag,ChartNoAxesCombined} from 'lucide-react';

function Spark({accent}:{accent:string}){return <div className="spark" aria-label="Upward trend chart"><i style={{height:'24%',background:accent}}/><i style={{height:'42%',background:accent}}/><i style={{height:'35%',background:accent}}/><i style={{height:'66%',background:accent}}/><i style={{height:'58%',background:accent}}/><i style={{height:'86%',background:accent}}/><i style={{height:'74%',background:accent}}/></div>}
function Shell({id,accent}:{id:TemplateId,accent:string}){
 const icons={analytics:<ChartNoAxesCombined/>,commerce:<ShoppingBag/>,fleet:<Truck/>,clinic:<CalendarDays/>,fintech:<WalletCards/>};
 return <div className={'dashmock dash-'+id}>
  <aside><b className="mocklogo">{icons[id]}</b><i/><i/><i/><i/><span/></aside>
  <div className="dashmain"><header><div><small>Workspace</small><b>{id==='analytics'?'Performance overview':id==='commerce'?'Order operations':id==='fleet'?'Live dispatch':id==='clinic'?'Appointments': 'Financial overview'}</b></div><div className="mockactions"><Search/><Bell/><span>RC</span></div></header>
  {id==='clinic'?<Clinic accent={accent}/>:id==='fleet'?<Fleet accent={accent}/>:id==='commerce'?<Commerce accent={accent}/>:<Metrics accent={accent} fintech={id==='fintech'}/>}</div>
 </div>
}

